//#region src/resolve.ts
const partCounts = [
	heads.length,
	eyes.length,
	mouths.length,
	hair.length,
	bodies.length,
	accessories.length,
	palettes.length
];
/**
* Resolves an input string to a full AvatarConfig.
* Each part is independently hashed so adding/removing variants
* from one part doesn't cascade changes to others.
*/
function resolve(input, overrides) {
	const pick = (slotIndex, count) => hashNth(input, slotIndex) % count;
	return {
		head: overrides?.head ?? pick(0, partCounts[0]),
		eyes: overrides?.eyes ?? pick(1, partCounts[1]),
		mouth: overrides?.mouth ?? pick(2, partCounts[2]),
		hair: overrides?.hair ?? pick(3, partCounts[3]),
		body: overrides?.body ?? pick(4, partCounts[4]),
		accessory: overrides?.accessory ?? pick(5, partCounts[5]),
		palette: pick(6, partCounts[6]),
		rotation: pick(7, 9)
	};
}

//#endregion
//#region src/compose.ts
/**
* Creates an empty 16x16 grid of zeros (transparent).
*/
function emptyGrid() {
	return Array.from({ length: GRID_SIZE }, () => new Array(GRID_SIZE).fill(0));
}
/**
* Merges a source layer onto a target grid.
* Non-zero pixels in the source overwrite the target.
*/
function mergeLayer(target, source) {
	for (let y = 0; y < GRID_SIZE; y++) for (let x = 0; x < GRID_SIZE; x++) if (source[y][x] !== 0) target[y][x] = source[y][x];
}
/**
* Merges source pixels onto target only where target has the given mask token.
* Used to apply body patterns only within the body silhouette.
*/
function maskMergeLayer(target, source, maskToken) {
	for (let y = 0; y < GRID_SIZE; y++) for (let x = 0; x < GRID_SIZE; x++) if (source[y][x] !== 0 && target[y][x] === maskToken) target[y][x] = source[y][x];
}
/**
* Composes all part layers into a single 16x16 grid of color tokens.
* Head first (base body shape), then body patterns masked onto body pixels,
* then eyes, mouth, hair, accessories on top.
*/
function compose(config) {
	const grid = emptyGrid();
	mergeLayer(grid, heads[config.head]);
	maskMergeLayer(grid, bodies[config.body], 1);
	mergeLayer(grid, eyes[config.eyes]);
	mergeLayer(grid, mouths[config.mouth]);
	mergeLayer(grid, hair[config.hair]);
	mergeLayer(grid, accessories[config.accessory]);
	return grid;
}

